import { NextResponse } from "next/server";
import { start } from "workflow/api";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { enableBankingClient } from "@/lib/bank/enable-banking";
import { bankAccountNames, psuFrom, serviceDb } from "@/lib/bank/server";
import { encryptToken } from "@/lib/bank/token-crypto";
import { syncBankConnection } from "@/workflows/bank-sync";

const querySchema = z.object({ state: z.string().uuid(), code: z.string().min(1).max(2000).optional(), error: z.string().max(200).optional() });

// The bank redirects here. The state must match a fresh pending connection in the caller's workspace.
export async function GET(request: Request) {
  const back = (result: string) => NextResponse.redirect(new URL(`/import?bank=${result}`, request.url), 303);
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.redirect(new URL("/login", request.url), 303); }
  const query = querySchema.safeParse(Object.fromEntries(new URL(request.url).searchParams));
  if (!query.success) return back("invalid");
  const db = serviceDb();
  const workspaceId = context.workspace.id;
  const pending = await db.from("bank_connections").select("id, aspsp_name, created_at").eq("auth_state", query.data.state)
    .eq("workspace_id", workspaceId).eq("status", "pending").maybeSingle();
  if (pending.error || !pending.data || Date.now() - Date.parse(pending.data.created_at) > 3_600_000) return back("invalid");
  const connectionId: string = pending.data.id;
  const fail = async (message: string) => {
    await db.from("bank_connections").update({ status: "error", last_error: message }).eq("id", connectionId).eq("status", "pending");
    return back("error");
  };
  if (!query.data.code || query.data.error) return fail(query.data.error ? `The bank returned ${query.data.error}` : "The bank did not return a consent code");
  try {
    const psu = psuFrom(request);
    const session = await enableBankingClient().createSession(query.data.code, psu);
    const names = bankAccountNames(pending.data.aspsp_name, session.accounts);
    const linked = await db.from("bank_connection_accounts").insert(session.accounts.map((account, index) => ({
      connection_id: connectionId, workspace_id: workspaceId, provider_account_uid: account.uid,
      iban: account.account_id?.iban?.replace(/\s/g, "") ?? null, currency_code: account.currency, account_name: names[index],
    })));
    if (linked.error) throw linked.error;
    // The status filter makes the state single-use even if the callback is replayed concurrently.
    const activated = await db.from("bank_connections").update({ status: "active", session_id_encrypted: encryptToken(session.session_id, connectionId),
      valid_until: session.access.valid_until, last_error: null }).eq("id", connectionId).eq("status", "pending").select("id").single();
    if (activated.error) throw activated.error;
    // A reconnect supersedes older connections to the same bank; account names match, so imports land in the same accounts.
    await db.from("bank_connections").update({ status: "revoked", session_id_encrypted: null }).eq("workspace_id", workspaceId)
      .eq("aspsp_name", pending.data.aspsp_name).in("status", ["active", "expired", "error"]).neq("id", connectionId);
    await start(syncBankConnection, [connectionId, workspaceId, psu]);
    return back("connected");
  } catch {
    return fail("The bank session could not be created");
  }
}
import { NextResponse } from "next/server";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { enableBankingClient, enableBankingConfigured } from "@/lib/bank/enable-banking";
import { consentValidUntil, psuFrom, serviceDb } from "@/lib/bank/server";
import { getEnv } from "@/lib/env";

const bodySchema = z.object({ aspspName: z.string().trim().min(1).max(200), country: z.string().regex(/^[A-Z]{2}$/) }).strict();

// Starts consent: a pending connection holds the redirect state, the browser goes to the bank.
export async function POST(request: Request) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
  if (!enableBankingConfigured() || !process.env.SUPABASE_SERVICE_ROLE_KEY) return NextResponse.json({ error: "Bank sync is not configured" }, { status: 503 });
  const body = bodySchema.safeParse(await request.json().catch(() => null));
  if (!body.success) return NextResponse.json({ error: "Choose a bank" }, { status: 400 });
  try {
    const client = enableBankingClient();
    const aspsp = (await client.listAspsps(body.data.country)).find(bank => bank.name === body.data.aspspName);
    if (!aspsp) return NextResponse.json({ error: "That bank is not available" }, { status: 400 });
    const pending = await serviceDb().from("bank_connections").insert({ workspace_id: context.workspace.id, aspsp_name: aspsp.name, aspsp_country: aspsp.country })
      .select("auth_state").single();
    if (pending.error) throw pending.error;
    const { url } = await client.startAuthorization({
      aspsp: { name: aspsp.name, country: aspsp.country }, validUntil: consentValidUntil(aspsp.maximum_consent_validity),
      state: pending.data.auth_state, redirectUrl: new URL("/api/bank/callback", getEnv().NEXT_PUBLIC_APP_URL).toString(), psu: psuFrom(request),
    });
    return NextResponse.json({ url });
  } catch {
    return NextResponse.json({ error: "The bank connection could not be started" }, { status: 502 });
  }
}
import { NextResponse } from "next/server";
import { requireWorkspace } from "@/lib/auth";
import { enableBankingConfigured } from "@/lib/bank/enable-banking";

// Connected banks for the UI. RLS plus the column grant keep the encrypted session out of reach.
export async function GET() {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
  const { data, error } = await context.supabase.from("bank_connections")
    .select("id, aspsp_name, aspsp_country, status, valid_until, last_synced_at, last_error, accounts:bank_connection_accounts(provider_account_uid, account_name, currency_code, last_booked_on)")
    .eq("workspace_id", context.workspace.id).in("status", ["active", "expired", "error"]).order("created_at", { ascending: false });
  if (error) return NextResponse.json({ error: "Connected banks are unavailable" }, { status: 500 });
  return NextResponse.json({ configured: enableBankingConfigured(), connections: data });
}
import { createClient } from "@supabase/supabase-js";
import { maskAccountNumber } from "@/lib/csv";
import { enableBankingClient, enableBankingConfigured, type BankAccount, type PsuContext } from "./enable-banking";
import { decryptToken } from "./token-crypto";

// Bank tables are service_role-only for writes and for the encrypted session column.
export function serviceDb() {
  const url = process.env.NEXT_PUBLIC_SUPABASE_URL, key = process.env.SUPABASE_SERVICE_ROLE_KEY;
  if (!url || !key) throw new Error("Bank sync service is not configured");
  return createClient(url, key, { auth: { persistSession: false, autoRefreshToken: false } });
}

export function psuFrom(request: Request): PsuContext {
  return {
    ip: request.headers.get("x-forwarded-for")?.split(",")[0].trim() || request.headers.get("x-real-ip") || "127.0.0.1",
    userAgent: (request.headers.get("user-agent") ?? "Moneo").slice(0, 500),
  };
}

// The Moneo account each bank account imports into: bank name + masked IBAN, so a reconnect
// lands in the same account. Same-named accounts (multi-currency pockets) get the currency appended.
export function bankAccountNames(aspspName: string, accounts: BankAccount[]) {
  const base = accounts.map(account => {
    const label = account.account_id?.iban ? maskAccountNumber(account.account_id.iban) : account.name || account.product || account.currency;
    return `${aspspName} ${label}`.trim();
  });
  return base.map((name, index) => Array.from(base.filter(other => other === name).length > 1 ? `${name} ${accounts[index].currency}` : name).slice(0, 100).join(""));
}

export function consentValidUntil(maximumSeconds: number | null | undefined, now = Date.now()) {
  // ponytail: 90 days when the bank doesn't publish a maximum; most allow 180 (issue #82).
  return new Date(now + (maximumSeconds ?? 90 * 86_400) * 1000);
}

// Before a workspace reset deletes the rows, end each consent at Enable Banking. Best effort:
// a session that can't be revoked here still expires at its valid_until.
export async function revokeBankSessions(workspaceId: string) {
  if (!enableBankingConfigured() || !process.env.SUPABASE_SERVICE_ROLE_KEY) return;
  try {
    const { data } = await serviceDb().from("bank_connections").select("id, session_id_encrypted").eq("workspace_id", workspaceId).not("session_id_encrypted", "is", null);
    const client = enableBankingClient();
    await Promise.allSettled((data ?? []).map(async row => client.deleteSession(decryptToken(row.session_id_encrypted, row.id))));
  } catch { /* the reset itself must not depend on the bank */ }
}
