import { NextResponse } from "next/server";
import { start } from "workflow/api";
import { z } from "zod";
import { requireWorkspace } from "@/lib/auth";
import { enableBankingConfigured } from "@/lib/bank/enable-banking";
import { psuFrom } from "@/lib/bank/server";
import { syncBankConnection } from "@/workflows/bank-sync";

// "Sync now" is user-present (PSU headers), so it doesn't use the background fetch allowance.
export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try { context = await requireWorkspace(); } catch { return NextResponse.json({ error: "Unauthorized" }, { status: 401 }); }
  if (!enableBankingConfigured() || !process.env.SUPABASE_SERVICE_ROLE_KEY) return NextResponse.json({ error: "Bank sync is not configured" }, { status: 503 });
  const id = z.string().uuid().safeParse((await params).id);
  if (!id.success) return NextResponse.json({ error: "Not found" }, { status: 404 });
  const connection = await context.supabase.from("bank_connections").select("status, last_synced_at").eq("id", id.data).eq("workspace_id", context.workspace.id).maybeSingle();
  if (connection.error || !connection.data) return NextResponse.json({ error: "Not found" }, { status: 404 });
  if (connection.data.status !== "active") return NextResponse.json({ error: "Reconnect this bank before syncing" }, { status: 409 });
  if (connection.data.last_synced_at && Date.now() - Date.parse(connection.data.last_synced_at) < 60_000)
    return NextResponse.json({ error: "Synced less than a minute ago" }, { status: 429 });
  await start(syncBankConnection, [id.data, context.workspace.id, psuFrom(request)]);
  return NextResponse.json({ status: "started" });
}
import { NextResponse } from "next/server";
import { requireWorkspace } from "@/lib/auth";

type UndoPreview = {
  import_id: string;
  filename: string;
  status: string;
  total_rows: number;
  new_rows: number;
  matched_rows: number;
  review_rows: number;
  rejected_rows: number;
  deletable_transactions: number;
  deletable_balances: number;
  blockers: string[];
  safe: boolean;
};

export async function GET(_request: Request, { params }: { params: Promise<{ id: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try {
    context = await requireWorkspace();
  } catch {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const { id } = await params;
  const result = await context.supabase.rpc("preview_import_undo", { p_import_id: id });
  if (result.error) return NextResponse.json({ error: result.error.message }, { status: 400 });
  return NextResponse.json(result.data as UndoPreview);
}

export async function POST(request: Request, { params }: { params: Promise<{ id: string }> }) {
  let context: Awaited<ReturnType<typeof requireWorkspace>>;
  try {
    context = await requireWorkspace();
  } catch {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }
  const { id } = await params;
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: "Confirmation with counts is required" }, { status: 400 });
  }
  if (!body || typeof body !== "object" || Array.isArray(body)) {
    return NextResponse.json({ error: "Confirm undo with current preview counts" }, { status: 400 });
  }
  const input = body as { confirm?: unknown; expectedTransactions?: unknown; expectedBalances?: unknown };
  if (
    input.confirm !== true ||
    typeof input.expectedTransactions !== "number" ||
    !Number.isInteger(input.expectedTransactions) ||
    input.expectedTransactions < 0 ||
    typeof input.expectedBalances !== "number" ||
    !Number.isInteger(input.expectedBalances) ||
    input.expectedBalances < 0
  ) {
    return NextResponse.json({ error: "Confirm undo with current preview counts" }, { status: 400 });
  }
  const result = await context.supabase.rpc("undo_import", {
    p_import_id: id,
    p_expected_transactions: input.expectedTransactions,
    p_expected_balances: input.expectedBalances,
  });
  if (result.error) return NextResponse.json({ error: result.error.message }, { status: 400 });
  return NextResponse.json(result.data);
}

